// tcMake typechecks an OMAKE node.
func (syncgoCtx *Context) tcMake(n *ir.CallExpr) ir.Node {
	if syncgoCtx == nil {
		panic("uninitialized compilation")
	}
	args := n.Args
	if len(args) == 0 {
		syncgoCtx.errorf("missing argument to make")
		n.SetType(nil)
		return n
	}

	n.Args = nil
	l := args[0]
	l = syncgoCtx.typecheck(l, ctxType)
	t := l.Type()
	if t == nil {
		n.SetType(nil)
		return n
	}

	i := 1
	var nn ir.Node
	switch t.Kind() {
	default:
		syncgoCtx.errorf("cannot make type %v", t)
		n.SetType(nil)
		return n

	case types.TSLICE:
		if i >= len(args) {
			syncgoCtx.errorf("missing len argument to make(%v)", t)
			n.SetType(nil)
			return n
		}

		l = args[i]
		i++
		l = syncgoCtx.Expr(l)
		var r ir.Node
		if i < len(args) {
			r = args[i]
			i++
			r = syncgoCtx.Expr(r)
		}

		if l.Type() == nil || (r != nil && r.Type() == nil) {
			n.SetType(nil)
			return n
		}
		if !syncgoCtx.checkmake(t, "len", &l) || r != nil && !syncgoCtx.checkmake(t, "cap", &r) {
			n.SetType(nil)
			return n
		}
		nn = syncgoCtx.IR.NewMakeExpr(n.Pos(), ir.OMAKESLICE, l, r)

	case types.TMAP:
		if i < len(args) {
			l = args[i]
			i++
			l = syncgoCtx.Expr(l)
			l = syncgoCtx.DefaultLit(l, syncgoCtx.IR.Types.Types[types.TINT])
			if l.Type() == nil {
				n.SetType(nil)
				return n
			}
			if !syncgoCtx.checkmake(t, "size", &l) {
				n.SetType(nil)
				return n
			}
		} else {
			l = syncgoCtx.IR.NewInt(syncgoCtx.IR.Types.Pos, 0)
		}
		nn = syncgoCtx.IR.NewMakeExpr(n.Pos(), ir.OMAKEMAP, l, nil)
		nn.SetEsc(n.Esc())

	case types.TCHAN:
		l = nil
		if i < len(args) {
			l = args[i]
			i++
			l = syncgoCtx.Expr(l)
			l = syncgoCtx.DefaultLit(l, syncgoCtx.IR.Types.Types[types.TINT])
			if l.Type() == nil {
				n.SetType(nil)
				return n
			}
			if !syncgoCtx.checkmake(t, "buffer", &l) {
				n.SetType(nil)
				return n
			}
		} else {
			l = syncgoCtx.IR.NewInt(syncgoCtx.IR.Types.Pos, 0)
		}
		nn = syncgoCtx.IR.NewMakeExpr(n.Pos(), ir.OMAKECHAN, l, nil)
	}

	if i < len(args) {
		syncgoCtx.errorf("too many arguments to make(%v)", t)
		n.SetType(nil)
		return n
	}

	nn.SetType(t)
	return nn
}

